<script setup>
import { computed, onMounted, ref } from 'vue'
import { getCities, getDistricts, getProvinces } from '../api/location'
import { getWindCore, getWindDates, getWindDistribution, getWindTrend, getRecentWind } from '../api/wind'
import BigScreenLayout from '../components/layout/BigScreenLayout.vue'
import ChartState from '../components/dashboard/ChartState.vue'
import DashboardPanel from '../components/dashboard/DashboardPanel.vue'
import WindTrendChart from '../components/wind/WindTrendChart.vue'
import WindDistributionChart from '../components/wind/WindDistributionChart.vue'
import { dataRegion, setDataRegion } from '../stores/regionStore'

const provinces=ref([]), cities=ref([]), districts=ref([]), availableDates=ref([])
const province=ref(dataRegion.province), city=ref(dataRegion.city), district=ref(dataRegion.district), startDate=ref(''), endDate=ref('')
const core=ref(null), recent=ref([]), trend=ref([]), distribution=ref([]), loading=ref(true), locationLoading=ref(false), error=ref(''), version=ref(0)
const standards=Object.freeze([['0','无风','0–0.2 m/s'],['1','软风','0.3–1.5 m/s'],['2','轻风','1.6–3.3 m/s'],['3','微风','3.4–5.4 m/s'],['4','和风','5.5–7.9 m/s'],['5','清劲风','8.0–10.7 m/s'],['6','强风','10.8–13.8 m/s'],['7','疾风','13.9–17.1 m/s'],['8','大风','17.2–20.7 m/s'],['9+','烈风及以上','≥20.8 m/s']])
const locationLabel=computed(()=>district.value?`${province.value} / ${city.value} / ${district.value}`:city.value?`${province.value} / ${city.value}`:province.value?`${province.value} / 省级汇总`:'全国汇总')
const dateLabel=computed(()=>startDate.value&&endDate.value?`${startDate.value} 至 ${endDate.value}`:'全部历史观测日期')
const startOptions=computed(()=>availableDates.value.filter(d=>!endDate.value||d<=endDate.value)), endOptions=computed(()=>availableDates.value.filter(d=>!startDate.value||d>=startDate.value))
const text=(v,u='')=>v===null||v===undefined||!Number.isFinite(Number(v))?'暂无数据':`${Number(v).toFixed(2)}${u}`
const levelText=computed(()=>core.value?.dominantLevel?`${core.value.dominantLevel.level}级 · ${core.value.dominantLevel.name}`:'暂无数据')
const conclusionItems=computed(()=>{const a=[];if(core.value?.avgWind!==null&&core.value?.avgWind!==undefined)a.push({label:'平均风速',text:`${locationLabel.value}平均风速 ${text(core.value.avgWind,' m/s')}，折合 ${text(core.value.avgWindKmh,' km/h')}。`});if(core.value?.maxWind!==null&&core.value?.maxWind!==undefined)a.push({label:'最大风速',text:`区域日均最大风速为 ${text(core.value.maxWind,' m/s')}，日期：${core.value.maxWindDate||'暂无数据'}。`});if(core.value?.dominantLevel)a.push({label:'主导等级',text:`${core.value.dominantLevel.name}（${core.value.dominantLevel.level}级）出现最多，共 ${core.value.dominantLevel.count} 天。`});return a})
const params=()=>Object.fromEntries(Object.entries({province:province.value,city:city.value,district:district.value,startDate:startDate.value,endDate:endDate.value}).filter(([,v])=>v))
const status=e=>e?.response?.status||0, message=(e,f)=>status(e)===404?'':`${f}：${e?.message||'请求失败'}`
function clear(){core.value=null;recent.value=[];trend.value=[];distribution.value=[]}
function chooseDates(values){availableDates.value=[...new Set(values)].sort((a,b)=>b.localeCompare(a));endDate.value=availableDates.value[0]||'';startDate.value=availableDates.value[Math.min(availableDates.value.length-1,29)]||''}
async function loadDates(token){const r=await getWindDates({province:province.value,city:city.value,district:district.value});if(token!==version.value)return false;chooseDates(Array.isArray(r.data)?r.data:[]);return availableDates.value.length>0}
async function loadData(token=++version.value){loading.value=true;error.value='';try{if(!(await loadDates(token))||token!==version.value)return;const p=params(),rs=await Promise.allSettled([getWindCore(p),getRecentWind(p),getWindTrend(p),getWindDistribution(p)]);if(token!==version.value)return;core.value=rs[0].status==='fulfilled'?rs[0].value.data:null;recent.value=rs[1].status==='fulfilled'&&Array.isArray(rs[1].value.data)?rs[1].value.data:[];trend.value=rs[2].status==='fulfilled'&&Array.isArray(rs[2].value.data)?rs[2].value.data:[];distribution.value=rs[3].status==='fulfilled'&&Array.isArray(rs[3].value.data)?rs[3].value.data:[];const fail=rs.find(x=>x.status==='rejected'&&status(x.reason)!==404);if(fail)error.value=message(fail.reason,'风力分析数据读取失败')}catch(e){if(token===version.value)error.value=message(e,'可用风速日期读取失败')}finally{if(token===version.value)loading.value=false}}
async function provinceChange(v){const t=++version.value;province.value=v;city.value='';district.value='';cities.value=[];districts.value=[];setDataRegion({province:v,city:'',district:'',scope:v?'province':'country'});clear();locationLoading.value=true;try{if(v){const r=await getCities({province:v});if(t!==version.value)return;cities.value=r.data||[]}await loadData(t)}catch(e){if(t===version.value)error.value=message(e,'城市列表读取失败')}finally{if(t===version.value)locationLoading.value=false}}
async function cityChange(v){const t=++version.value;city.value=v;district.value='';districts.value=[];setDataRegion({province:province.value,city:v,district:'',scope:v?'city':province.value?'province':'country'});clear();locationLoading.value=true;try{if(v){const r=await getDistricts({province:province.value,city:v});if(t!==version.value)return;districts.value=r.data||[]}await loadData(t)}catch(e){if(t===version.value)error.value=message(e,'区县列表读取失败')}finally{if(t===version.value)locationLoading.value=false}}
async function districtChange(v){const t=++version.value;district.value=v;setDataRegion({province:province.value,city:city.value,district:v,scope:v?'district':city.value?'city':province.value?'province':'country'});clear();locationLoading.value=true;try{await loadData(t)}finally{if(t===version.value)locationLoading.value=false}}
function rangeChange(kind,v){if(kind==='start')startDate.value=v;else endDate.value=v;if(startDate.value>endDate.value){if(kind==='start')endDate.value=v;else startDate.value=v}}
async function initial(){try{const r=await getProvinces();provinces.value=r.data||[];await loadData()}catch(e){error.value=message(e,'省份列表读取失败');loading.value=false}}
onMounted(initial)
</script>
<template>
<BigScreenLayout page-number="4" title="风力分析" description="基于历史天气数据分析区域风速变化趋势。" header-status="风力历史数据" toolbar-status="历史观测分析 · 不代表天气预报" :data-date="endDate">
<template #filters><div class="wind-filter-layout"><div class="wind-filters"><span class="wind-filter-title">区域筛选</span><label>省级行政区<select :value="province" :disabled="locationLoading" @change="provinceChange($event.target.value)"><option value="">全国</option><option v-for="x in provinces" :key="x" :value="x">{{x}}</option></select></label><label>城市<select :value="city" :disabled="locationLoading||!province" @change="cityChange($event.target.value)"><option value="">全部城市</option><option v-for="x in cities" :key="x" :value="x">{{x}}</option></select></label><label>区县<select :value="district" :disabled="locationLoading||!city" @change="districtChange($event.target.value)"><option value="">全部区县</option><option v-for="x in districts" :key="x" :value="x">{{x}}</option></select></label><label>时间范围<select :value="startDate" :disabled="loading||locationLoading||!availableDates.length" @change="rangeChange('start',$event.target.value)"><option v-for="x in startOptions" :key="`s${x}`" :value="x">{{x.replaceAll('-','/')}}</option></select> ~ <select :value="endDate" :disabled="loading||locationLoading||!availableDates.length" @change="rangeChange('end',$event.target.value)"><option v-for="x in endOptions" :key="`e${x}`" :value="x">{{x.replaceAll('-','/')}}</option></select></label><button type="button" :disabled="loading||locationLoading||!availableDates.length" @click="loadData()">查询</button></div><span class="wind-filter-caption">{{locationLabel}} · {{dateLabel}}</span></div></template>
<p v-if="error" class="wind-alert">{{error}}</p><div class="wind-page"><DashboardPanel title="风力核心指标" :subtitle="`${locationLabel} · ${dateLabel}`"><ChartState :loading="loading" :error="''" :empty="!core" empty-message="当前筛选范围暂无风速数据"><div class="wind-metric-grid"><article v-for="item in [{i:'≈',l:'平均风速',v:text(core?.avgWind,' m/s'),s:'有效区域日均值'},{i:'↑',l:'最大风速',v:text(core?.maxWind,' m/s'),s:core?.maxWindDate||'暂无数据'},{i:'旗',l:'主导风力等级',v:levelText,s:'按有效观测日统计'},{i:'↻',l:'风速换算',v:text(core?.avgWindKmh,' km/h'),s:'平均风速 × 3.6'}]" :key="item.l"><span>{{item.i}}</span><div><small>{{item.l}}</small><strong>{{item.v}}</strong><em>{{item.s}}</em></div></article></div></ChartState></DashboardPanel><div class="wind-grid"><DashboardPanel class="wind-trend" title="风速变化趋势" subtitle="近30天区域日均风速"><WindTrendChart :data="trend" :loading="loading" :error="''"/></DashboardPanel><DashboardPanel class="wind-distribution" title="风力等级分布" subtitle="有效区域日均风速观测日"><WindDistributionChart :data="distribution" :loading="loading" :error="''"/></DashboardPanel><DashboardPanel class="wind-standard" title="蒲福风级表" subtitle="风力等级科学说明"><div class="wind-standard-grid"><div v-for="x in standards" :key="x[0]"><strong>{{x[0]}}级</strong><b>{{x[1]}}</b><span>{{x[2]}}</span></div></div></DashboardPanel><DashboardPanel class="wind-recent" title="近7日风况详情" subtitle="筛选范围结束日期向前的有效观测日"><ChartState :loading="loading" :error="''" :empty="!recent.length" empty-message="暂无风速观测数据"><div class="wind-recent-grid"><article v-for="x in recent" :key="x.date"><b>{{x.date}}</b><span>平均 {{text(x.avgWind,' m/s')}}</span><span>最大 {{text(x.maxWind,' m/s')}}</span><em>{{x.level?`${x.level.level}级 ${x.level.name}`:'暂无等级'}}</em></article></div></ChartState></DashboardPanel><DashboardPanel class="wind-conclusion" title="风力分析结论" subtitle="根据真实观测数据计算"><ChartState :loading="loading" :error="''" :empty="!conclusionItems.length" empty-message="暂无足够真实数据生成结论"><div class="wind-conclusions"><div v-for="x in conclusionItems" :key="x.label"><strong>{{x.label}}</strong><span>{{x.text}}</span></div></div></ChartState></DashboardPanel></div></div>
</BigScreenLayout></template>
<style scoped>
.wind-filter-layout{display:flex;align-items:center;gap:10px;padding:7px 13px;background:linear-gradient(90deg,rgb(6 42 81/.92),rgb(4 28 61/.84));border:1px solid rgb(35 143 211/.58);border-radius:6px}.wind-filters{display:flex;flex:1;align-items:center;flex-wrap:wrap;gap:7px 13px}.wind-filter-title{color:var(--accent-cyan);font-weight:700}.wind-filters label{display:inline-flex;align-items:center;gap:6px;color:var(--text-muted);font-size:11px}.wind-filters select,.wind-filters button{height:32px;padding:5px 20px 5px 9px;color:var(--text-primary);font:inherit;background:linear-gradient(180deg,#0b315f,#08254b);border:1px solid rgb(45 151 216/.68);border-radius:4px}.wind-filters button{padding:0 14px;color:#eafaff;background:#0b5fa8;font-weight:700}.wind-filter-caption{color:var(--text-muted);font-size:10px;white-space:nowrap}.wind-alert{margin:0;padding:8px 12px;color:var(--danger);background:rgb(100 24 48/.32);border:1px solid rgb(255 125 134/.4);border-radius:6px}.wind-page{display:flex;min-height:0;flex:1;flex-direction:column;gap:12px}.wind-metric-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.wind-metric-grid article{display:flex;min-height:104px;align-items:center;gap:13px;padding:14px;background:linear-gradient(145deg,rgb(7 49 94/.8),rgb(3 26 58/.78));border:1px solid rgb(36 145 211/.52);border-radius:7px}.wind-metric-grid article>span{display:grid;width:48px;height:48px;place-items:center;color:var(--accent-cyan);font-size:20px;background:rgb(12 94 157/.38);border:1px solid rgb(73 205 255/.45);border-radius:50%}.wind-metric-grid small,.wind-metric-grid em{display:block;color:var(--text-secondary);font-size:12px;font-style:normal}.wind-metric-grid strong{display:block;margin-top:5px;color:var(--text-primary);font-size:23px}.wind-metric-grid em{margin-top:6px;color:var(--text-muted);font-size:10px}.wind-grid{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(360px,1fr);grid-template-areas:'trend distribution' 'standard standard' 'recent conclusion';gap:12px}.wind-trend{grid-area:trend;min-height:310px}.wind-distribution{grid-area:distribution;min-height:310px}.wind-standard{grid-area:standard}.wind-recent{grid-area:recent;min-height:200px}.wind-conclusion{grid-area:conclusion;min-height:200px}.wind-standard-grid{display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:5px}.wind-standard-grid div{display:flex;min-height:90px;align-items:center;flex-direction:column;gap:5px;padding:7px 3px;text-align:center;background:rgb(9 45 85/.78);border:1px solid rgb(45 151 216/.56);border-radius:5px}.wind-standard-grid strong{width:100%;padding:4px 1px;color:#77c8ff;background:rgb(62 137 190/.35);border-radius:3px}.wind-standard-grid b{color:var(--text-primary);font-size:11px}.wind-standard-grid span{color:var(--text-secondary);font-size:9px}.wind-recent-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px}.wind-recent-grid article{display:flex;min-height:128px;align-items:center;flex-direction:column;gap:7px;padding:10px 5px;text-align:center;background:rgb(4 36 74/.72);border:1px solid rgb(37 143 210/.45);border-radius:6px}.wind-recent-grid b{color:var(--text-primary);font-size:11px}.wind-recent-grid span{color:#8fd4ff;font-size:11px}.wind-recent-grid em{margin-top:auto;color:#54e0b2;font-size:11px;font-style:normal}.wind-conclusions{display:grid;gap:8px}.wind-conclusions div{display:grid;grid-template-columns:90px 1fr;gap:10px;padding:9px 12px;color:var(--text-secondary);font-size:12px;background:rgb(5 37 76/.68);border:1px solid rgb(42 148 211/.42);border-radius:6px}.wind-conclusions strong{color:var(--accent-cyan)}@media(max-width:1100px){.wind-metric-grid{grid-template-columns:repeat(2,1fr)}.wind-grid{grid-template-columns:1fr;grid-template-areas:'trend' 'distribution' 'standard' 'recent' 'conclusion'}.wind-recent-grid{grid-template-columns:repeat(4,1fr)}.wind-standard-grid{grid-template-columns:repeat(5,1fr)}}@media(max-width:680px){.wind-filter-layout{align-items:flex-start;flex-direction:column}.wind-filters{align-items:flex-start;flex-direction:column}.wind-metric-grid,.wind-recent-grid{grid-template-columns:repeat(2,1fr)}.wind-standard-grid{grid-template-columns:repeat(2,1fr)}.wind-conclusions div{grid-template-columns:1fr}}
</style>
